import 'dart:convert';
import 'dart:io';
import 'classUser.dart';
import 'package:http/http.dart' as http;

Future<Map<String, String>> _loadConfigHeaders() async {
  final configPath = 'config/user_service_config.json';
  String apiKey = '';
  String baseUrl = 'https://reqres.in';
  final file = File(configPath);
  if (await file.exists()) {
    try {
      final contents = await file.readAsString();
      final Map<String, dynamic> json = jsonDecode(contents);
      apiKey = json['apiKey'] as String? ?? apiKey;
      baseUrl = json['baseUrl'] as String? ?? baseUrl;
      print('Loaded config: baseUrl=$baseUrl');
    } catch (e) {
      print('Error reading config file: $e');
    }
  } else {
    print('Config file not found at $configPath, using defaults.');
  }
  return {'apiKey': apiKey, 'baseUrl': baseUrl};
}

Future<void> getReqRespService() async {
  final cfg = await _loadConfigHeaders();
  final baseUrl = cfg['baseUrl']!;
  final apiKey = cfg['apiKey']!;

  final urlString = '$baseUrl/api/users';
  final url = Uri.parse(urlString);
  final headers = <String, String>{};
  if (apiKey.isNotEmpty) headers['x-api-key'] = apiKey;

  final res = await http.get(url, headers: headers);
  final body = jsonDecode(res.body) as Map<String, dynamic>;
  final List<dynamic> data = body['data'] as List<dynamic>;
  print(data);
  final users = data.map((e) => User.fromJson(e)).toList();
  for (var user in users) {
    print(user.id);
  }
  print(url);
}

Future<void> getSingleUser(int id) async {
  final cfg = await _loadConfigHeaders();
  final baseUrl = cfg['baseUrl']!;
  final apiKey = cfg['apiKey']!;

  final urlString = '$baseUrl/api/users/$id';
  final url = Uri.parse(urlString);
  final headers = <String, String>{};
  if (apiKey.isNotEmpty) headers['x-api-key'] = apiKey;

  final res = await http.get(url, headers: headers);
  print(url);
  final body = jsonDecode(res.body) as Map<String, dynamic>;
  print('${body['data']}');
  final user = User.fromJson(body['data']);
  print(user);
}

Future<User?> getSingleUserObject(int id) async {
  try {
    await getSingleUser(id);
    return null;
  } catch (e) {
    print('Error in getSingleUserObject: $e');
    return null;
  }
}

Future<List<User>> getListUsersObject() async {
  try {
    await getReqRespService();
    return <User>[];
  } catch (e) {
    print('Error in getListUsersObject: $e');
    return <User>[];
  }
}

void main() async {
  await getReqRespService();
  await getSingleUser(2);
}
